<script lang="ts">
  import { iconSizes } from '../lib/icons';
  import { onMount, untrack } from 'svelte';
  import { ChevronDown, CircleCheck, RefreshCw, TriangleAlert, ArrowUpRight } from '@lucide/svelte';
  import { HomeDataStore, type AttentionSnapshot, type HomeDataState } from '../lib/home';
  let {active=true,onnavigate}:{active?:boolean;onnavigate?:(event:MouseEvent,path:string)=>void}=$props();
  let summary=$state<HomeDataState<AttentionSnapshot>>({data:null,loading:false,error:''});
  const store=new HomeDataStore<AttentionSnapshot>('/api/home/attention',next=>summary=next);
  let expanded=$state(false);let mounted=false;
  const parts=$derived(Object.entries(summary.data?.counts??{}).filter(([,count])=>count>0).map(([kind,count])=>`${count} ${kind==='service'?'service issue':kind==='update'?'container update':kind==='check'?'incomplete check':kind==='feed'?'feed failure':'saved-copy failure'}${count===1?'':'s'}`).join(' · '));
  $effect(()=>{const visible=active;if(mounted&&visible)untrack(()=>{void store.refresh();});});
  onMount(()=>{mounted=true;void store.refresh();const refresh=()=>{if(active&&!document.hidden)void store.refresh();};const timer=setInterval(refresh,60000);window.addEventListener('focus',refresh);document.addEventListener('visibilitychange',refresh);window.addEventListener('clonepage:reading-changed',refresh);return()=>{mounted=false;store.dispose();clearInterval(timer);window.removeEventListener('focus',refresh);document.removeEventListener('visibilitychange',refresh);window.removeEventListener('clonepage:reading-changed',refresh);};});
</script>
<section class="attention home-surface" aria-label="Needs attention">
  <div class="summary"><button class="overview" onclick={()=>expanded=!expanded} aria-expanded={expanded} disabled={!summary.data?.total}>{#if summary.error||summary.data?.total}<TriangleAlert size={iconSizes.section}/>{:else if summary.data}<CircleCheck size={iconSizes.section}/>{:else}<RefreshCw size={iconSizes.action}/>{/if}<span><strong>{summary.error?'Attention summary unavailable':!summary.data?'Checking what needs attention…':summary.data.total?'Needs attention':'Nothing needs attention'}</strong>{#if parts}<small>{parts}</small>{:else if summary.data&&!summary.error}<small>Your configured checks have no issues to report.</small>{/if}</span>{#if summary.data?.total}<ChevronDown size={iconSizes.inline}/>{/if}</button><button class="refresh" disabled={summary.loading} onclick={()=>store.refresh()} aria-label="Refresh attention summary"><RefreshCw size={iconSizes.action}/></button></div>
  {#if summary.error}<p class="error" role="status">{summary.error}{summary.data?' Showing previous details.':''}</p>{/if}
  {#if expanded&&summary.data?.items.length}<ul>{#each summary.data.items as item(item.id)}<li><span class="kind">{item.kind==='update'?'UPDATE':item.kind==='check'?'CHECK':item.kind==='service'?'SERVICE':item.kind==='feed'?'FEED':'SAVED COPY'}</span><a href={item.href} target={item.href.startsWith('/')?undefined:'_blank'} rel="noopener noreferrer" onclick={event=>{if(item.href.startsWith('/'))onnavigate?.(event,item.href);}}><strong>{item.title}</strong><small>{item.detail}</small></a>{#if !item.href.startsWith('/')}<ArrowUpRight size={iconSizes.inline}/>{/if}</li>{/each}</ul>{/if}
</section>
<style>
  .attention{margin:0}.summary,.overview{display:flex;align-items:center;gap:12px}.summary{justify-content:space-between}.overview{flex:1;text-align:left;color:var(--highlight);background:none;border:0;padding:0;min-width:0}.overview>span{flex:1}.overview:disabled{cursor:default;opacity:1}.overview strong{display:block;color:var(--text);font-size:12px;font-weight:500}.overview small{display:block;color:var(--muted);font-size:11px;margin-top:5px;line-height:1.6}.refresh{background:none;border:0;color:var(--muted);padding:8px;border-radius:6px}ul{list-style:none;margin:18px 0 0;padding:0;border-top:1px solid var(--line)}li{display:flex;align-items:flex-start;gap:12px;padding:15px 0;border-bottom:1px solid var(--line)}li:last-child{border:0;padding-bottom:0}.kind{flex-shrink:0;width:72px;color:var(--warning);font-size:9px;letter-spacing:.07em;line-height:1.9}li a{color:var(--text);text-decoration:none;min-width:0;flex:1}li strong{font-size:12px;line-height:1.7;font-weight:500}li small{display:block;color:var(--muted);font-size:11px;line-height:1.7;margin-top:3px;overflow-wrap:anywhere}li a:hover strong{text-decoration:underline}.error{font-size:11px;color:var(--warning);line-height:1.7}:is(a,button):focus-visible{outline:2px solid var(--highlight);outline-offset:4px}@media (max-width:540px){.kind{width:57px;font-size:8px}li{gap:8px}}@media (hover:none) and (pointer:coarse){button{min-height:44px;min-width:44px}}
</style>
